-- Schema 41: copy both constrained tables before swapping either.
CREATE TABLE new_fin_accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,institution TEXT NOT NULL,side TEXT NOT NULL CHECK(side IN ('asset','liability')),kind TEXT NOT NULL CHECK(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset','property','pension','insurance','precious_metal','credit_card','loan','other_liability')),counted INTEGER NOT NULL CHECK(counted IN (0,1)),opened_on TEXT NOT NULL,closed_on TEXT,notes TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),revision INTEGER NOT NULL CHECK(revision>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,CHECK((side='asset')=(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset','property','pension','insurance','precious_metal'))),CHECK(closed_on IS NULL OR closed_on>opened_on),CHECK(kind <> 'property' OR counted = 0));
CREATE TABLE new_fin_snapshot_entries(snapshot_id TEXT NOT NULL REFERENCES fin_snapshots(id),account_id TEXT NOT NULL REFERENCES fin_accounts(id),state TEXT NOT NULL CHECK(state IN ('entered','unchanged','missing')),amount_cents INTEGER CHECK(amount_cents BETWEEN 0 AND 99999999999),side TEXT NOT NULL CHECK(side IN ('asset','liability')),kind TEXT NOT NULL,counted INTEGER NOT NULL CHECK(counted IN (0,1)),PRIMARY KEY(snapshot_id,account_id),CHECK((state='missing')=(amount_cents IS NULL)),CHECK((side='asset')=(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset','property','pension','insurance','precious_metal'))),CHECK(kind <> 'property' OR counted = 0));
INSERT INTO new_fin_accounts(id,name,institution,side,kind,counted,opened_on,closed_on,notes,position,revision,created_at,updated_at,deleted_at) SELECT id,name,institution,side,kind,counted,opened_on,closed_on,notes,position,revision,created_at,updated_at,deleted_at FROM fin_accounts;
INSERT INTO new_fin_snapshot_entries(snapshot_id,account_id,state,amount_cents,side,kind,counted) SELECT snapshot_id,account_id,state,amount_cents,side,kind,counted FROM fin_snapshot_entries;
